const input = $input.first().json;
const headers = input.headers ?? {};
const token = Object.entries(headers).find(([name]) => name.toLowerCase() === 'x-n8n-webhook-token')?.[1];
const expected = $env.N8N_WEBHOOK_TOKEN;
if (!expected || !token || token !== expected) {
  throw new Error('Unauthorized anomaly notification webhook request');
}

const payload = input.body ?? input;
const anomaly = payload.anomalie;
const site = payload.site;
const organization = payload.organisation;
const recipients = organization?.emails_admin;
if (!anomaly?.id || !site?.nom || !organization?.nom || !Array.isArray(recipients) || recipients.length === 0) {
  throw new Error('Invalid anomaly notification payload');
}
if (recipients.some((email) => typeof email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))) {
  throw new Error('Invalid administrator email address in anomaly notification payload');
}

const percent = `${anomaly.ecart_pourcentage}%`;
const direction = anomaly.type === 'consumption_drop' ? 'a diminué' : 'a augmenté';
const subject = `[EcoScan] Anomalie de consommation - ${site.nom}`;
const text = [
  `Une anomalie de consommation ${direction} a été détectée pour ${site.nom} (${organization.nom}).`,
  '',
  `Sévérité : ${anomaly.severite}`,
  `Écart : ${percent}`,
  `Consommation observée : ${anomaly.valeur_observee} kWh`,
  `Consommation attendue : ${anomaly.valeur_attendue} kWh`,
  `Date de détection : ${anomaly.date_detection}`,
  '',
  `Consulter les anomalies du site : ${payload.url_api_anomalies}`,
  `Identifiant de l'anomalie : ${anomaly.id}`
].join('\n');

return [{ json: { recipients, subject, text } }];
